{[x;y]
    vals:"j"$y;
    ops:x;
    doPass:{[vals;ops;op1;op2]
        flags:(op1~/:ops) or (op2~/:ops);
        i:first where flags;
        a:vals[i];
        b:vals[i+1];
        op:ops[i];
        r:$[op~"**";a xexp b;
            op~"*";a*b;
            op~"//";a div b;
            op~"+";a+b;
            op~"-";a-b;
            '"bad op"];
        newvals:(i#vals),(enlist r),((i+2)_vals);
        newops:(i#ops),((i+1)_ops);
        (newvals;newops)
        };
    while[any "**"~/:ops;
        res:doPass[vals;ops;"**";"**"];
        vals:res[0];
        ops:res[1];
        ];
    while[any (("*"~/:ops) or ("//"~/:ops));
        res:doPass[vals;ops;"*";"//"];
        vals:res[0];
        ops:res[1];
        ];
    while[any (("+"~/:ops) or ("-"~/:ops));
        res:doPass[vals;ops;"+";"-"];
        vals:res[0];
        ops:res[1];
        ];
    first vals
    }

